fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
include!("stats.rs");
fn tree(dir:&Path,pins:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){tree(&e.path(),pins)}else{pins.insert(e.path().display().to_string(),hash(e.path()));}}}
fn cases(pattern:&str)->Vec<&'static str>{let mut v=vec!["ordinary-parent","ordinary-current","comba","cios"];if pattern=="butterfly"{v.push("ordinary-current-r4")}v}
fn invocation(label:&str,pattern:&str)->(String,&'static str){let parent=label=="ordinary-parent"||label=="comba";let root=if parent{P}else{R};let mode=if pattern=="butterfly"{match label{"comba"|"cios"=>"gaussian-r4-lazy","ordinary-current-r4"=>"ordinary-r4",_=>"ordinary-r2"}}else{if label=="comba"||label=="cios"{"gaussian"}else{"ordinary"}};(format!("{root}/target-native/release/probe"),mode)}
fn result(name:&str)->Value{let s=fs::read_to_string(Path::new(R).join("runs").join(name).join("stdout.log")).unwrap();serde_json::from_str(s.lines().find_map(|s|s.strip_prefix("RESULT ")).unwrap()).unwrap()}
