fn archive(root:&Path,dir:&Path,dest:&Path,index:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();if e.file_type().unwrap().is_dir(){if !name.starts_with("target"){archive(root,&p,dest,index)}continue}let rel=p.strip_prefix(root).unwrap();if rel.to_string_lossy().contains("loss-")&&name=="stdout.log"{continue}if !["rs","md","json","jsonl","log","txt","toml","lock"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("")){continue}let to=dest.join(rel);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&p,&to).unwrap();assert_eq!(hash(&p),hash(&to));index.insert(rel.display().to_string(),hash(to));}}
